  const whyIcons = [ICONS.target, ICONS.box, ICONS.coin, ICONS.wrench];
  const whyUs = WHY_US.map((w, i) => `<div class="why-item"><div class="wicon">${whyIcons[i] || ICONS.star}</div><div><h4>${w.title}</h4><p>${w.desc}</p></div></div>`).join('');

