function _seoulHash(s) { let h=0; for(let i=0;i<s.length;i++) h=(h*31+s.charCodeAt(i))|0; return Math.abs(h); }
function _seoulPick(salt, arr) { return arr[_seoulHash(salt)%arr.length]; }

